<?php
/**
 * Idempotent Master Resource Synchronizer for HERO LEGEND ORI (v206)
 * Safely upserts missing Ninjas (up to 221 Shibai Otsutsuki), Jutsus (1330),
 * Emblem/Ring Items (5200+), RoleGroups (263..267), Redeem Codes, and Server Config
 * without modifying or wiping existing player data.
 */
$envFile = __DIR__ . '/.env';
$env = [];
if (file_exists($envFile)) {
    foreach (file($envFile, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES) as $line) {
        $line = trim($line);
        if ($line === '' || $line[0] === '#' || strpos($line, '=') === false) continue;
        [$k, $v] = explode('=', $line, 2);
        $env[trim($k)] = trim($v, " \t\n\r\0\x0B\"'");
    }
}
$host = $env['DB_HOST'] ?? '127.0.0.1';
if ($host === 'localhost') $host = '127.0.0.1';
$port = $env['DB_PORT'] ?? '3306';
$db   = $env['DB_DATABASE'] ?? 'ninja_heroes';
$user = $env['DB_USERNAME'] ?? 'root';
$pass = $env['DB_PASSWORD'] ?? '';

try {
    $pdo = new PDO("mysql:host={$host};port={$port};dbname={$db};charset=utf8mb4", $user, $pass, [
        PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
    ]);
    $statements = [
