    "INSERT INTO `master_role_groups` (`id`,`name`,`description`,`roles`,`alter_self`,`skill_id`)\nVALUES (260,'The Endless War','Prime Kaguya, Prime Hagoromo, Hamura, Ashura, Indra, Hashirama Sage Mode, Madara Edo Tensei, Ten Tails Madara, Ten Tails Obito, Kakashi Hokage, Prime Naruto, Prime Sasuke join the battle at the same time. Attack, Defense, HP and Agility increase by 22% in battle.','188|187|162|170|171|146|145|148|190|180|209|208','alter(type=3,when=0,ratios=-22)|alter(type=11,when=1,ratios=999;122)|alter(type=12,when=1,ratios=999;122)|alter(type=14,when=1,ratios=999;122)',0)\nON DUPLICATE KEY UPDATE `name`=VALUES(`name`),`description`=VALUES(`description`),`roles`=VALUES(`roles`),`alter_self`=VALUES(`alter_self`),`skill_id`=VALUES(`skill_id`);",
